const database = require('./src/config/database');

(async () => {
  try {
    await database.ejecutar(
      "CREATE TABLE HORARIO_ASIGNADO (id_horario NUMBER GENERATED BY DEFAULT AS IDENTITY, id_empleado NUMBER NOT NULL, fecha DATE NOT NULL, hora_entrada_prog VARCHAR2(5) NOT NULL, hora_salida_prog VARCHAR2(5) NOT NULL, tipo_turno VARCHAR2(50) NOT NULL, id_asignacion NUMBER, CONSTRAINT pk_horario_asignado PRIMARY KEY (id_horario), CONSTRAINT fk_horario_asignado_empleado FOREIGN KEY (id_empleado) REFERENCES EMPLEADO (id_empleado), CONSTRAINT fk_horario_asignado_asig FOREIGN KEY (id_asignacion) REFERENCES ASIGNACION_HORARIO (id_asignacion), CONSTRAINT uq_horario_asignado UNIQUE (id_empleado, fecha))"
    );
    console.log('ok1');
  } catch (e) {
    console.log('e1', e.message);
  }
  try {
    await database.ejecutar(
      "CREATE TABLE SOLICITUD_RELEVO (id_solicitud NUMBER GENERATED BY DEFAULT AS IDENTITY, id_horario NUMBER NOT NULL, id_empleado_solicitante NUMBER NOT NULL, id_empleado_companero NUMBER NOT NULL, estado VARCHAR2(10) DEFAULT 'Pendiente' NOT NULL, fecha_solicitud TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, fecha_respuesta TIMESTAMP, CONSTRAINT pk_solicitud_relevo PRIMARY KEY (id_solicitud), CONSTRAINT fk_sr_horario FOREIGN KEY (id_horario) REFERENCES HORARIO_ASIGNADO (id_horario), CONSTRAINT fk_sr_solicitante FOREIGN KEY (id_empleado_solicitante) REFERENCES EMPLEADO (id_empleado), CONSTRAINT fk_sr_companero FOREIGN KEY (id_empleado_companero) REFERENCES EMPLEADO (id_empleado), CONSTRAINT ck_sr_estado CHECK (estado IN ('Pendiente','Confirmado','Rechazado')), CONSTRAINT ck_sr_distintos CHECK (id_empleado_solicitante <> id_empleado_companero))"
    );
    console.log('ok2');
  } catch (e) {
    console.log('e2', e.message);
  }
  process.exit(0);
})();
